import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { registerHooks } from 'node:module';
import { relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = process.cwd();
const reference = 'f71edbfcbccb33c2fbc424116c6684b4ed7596ad';
const mode = process.env.SPACEFACE_BASELINE_DIAG_MODE || 'current';
assert.ok(['current', 'controller', 'version-only'].includes(mode));
const changed = new Set(execFileSync('git', ['diff', '--name-only', reference, 'HEAD', '--', 'src', 'scripts'], { encoding: 'utf8' }).trim().split('\n'));
const audit = globalThis.__spacefaceBaselineDiagnosis = {
  mode, reference, overrides: [], observer: 'Read existing event trace; record entity motion after each ordinary step, before any requested reload. No authoritative writes.',
  motionColumns: ['id', 'occupantGeneration', 'type', 'alive', 'x', 'z', 'vx', 'vz', 'rot', 'angVel', 'prevX', 'prevZ', 'prevRot', 'hull', 'shield', 'cap'],
};
const sources = new Map();
const sha256 = (text) => createHash('sha256').update(text).digest('hex');
function replaceOnce(source, before, after) {
  assert.equal(source.split(before).length - 1, 1, `observer anchor must be unique: ${before}`);
  return source.replace(before, after);
}
function addReadOnlyObservation(source) {
  source = replaceOnce(source,
    '  const inspected = await run47a({ seed, ticks, tape, reloadAt, canonicalizeAt, physicsBackend, tacticalAI, counterTetherProbe, flightSystem });',
    '  const inspected = await run47a({ seed, ticks, tape, reloadAt, canonicalizeAt, physicsBackend, tacticalAI, counterTetherProbe, flightSystem, includeTrace: true });');
  source = replaceOnce(source, '    snapshot: inspected.snapshot,',
    '    snapshot: inspected.snapshot,\n    trace: inspected.trace,\n    combatTrace: inspected.combatTrace,\n    diagnosticMotionFrames: inspected.diagnosticMotionFrames,\n    diagnosticSources: globalThis.__spacefaceBaselineDiagnosis,');
  source = replaceOnce(source, '  const metrics = {\n', '  const diagnosticMotionFrames = [];\n  const metrics = {\n');
  source = replaceOnce(source, '    sim.step(SIM_DT);\n', `    sim.step(SIM_DT);
    diagnosticMotionFrames.push([state.tick, Array.from(state.entityList).sort((a, b) => a.id - b.id).map((e) => [
      e.id, e.occupantGeneration ?? null, e.type, e.alive,
      e.pos?.x ?? null, e.pos?.z ?? null, e.vel?.x ?? null, e.vel?.z ?? null,
      e.rot ?? null, e.angVel ?? null, e.prevPos?.x ?? null, e.prevPos?.z ?? null, e.prevRot ?? null,
      e.hull ?? null, e.shield ?? null, e.cap ?? null,
    ])]);
`);
  source = replaceOnce(source,
    '    ? { snapshot, sha256, metrics, traceSummary, trace, combatTrace, physicsBackend, scenarioContract: scenarioContractSummary }',
    '    ? { snapshot, sha256, metrics, traceSummary, trace, combatTrace, diagnosticMotionFrames, physicsBackend, scenarioContract: scenarioContractSummary }');
  return source;
}
registerHooks({ load(url, context, nextLoad) {
  const loaded = nextLoad(url, context);
  if (!url.startsWith('file:')) return loaded;
  const path = relative(root, fileURLToPath(url)).split(sep).join('/');
  if (path.startsWith('../') || path.startsWith('node_modules/')) return loaded;
  let source = typeof loaded.source === 'string' ? loaded.source : loaded.source ? Buffer.from(loaded.source).toString('utf8') : null;
  const override = mode === 'controller' ? changed.has(path) : mode === 'version-only' && path === 'src/data/saveVersion.js';
  if (override) {
    if (!sources.has(path)) sources.set(path, execFileSync('git', ['show', `${reference}:${path}`], { encoding: 'utf8' }));
    source = sources.get(path);
    audit.overrides.push({ path, sourceRef: reference, sha256: sha256(source) });
  }
  if (path === 'scripts/sf-sim-cli.mjs') {
    audit.cliUninstrumentedSha256 = sha256(source);
    source = addReadOnlyObservation(source);
    audit.cliObservedSha256 = sha256(source);
  }
  return source == null ? loaded : { ...loaded, source };
} });

