import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { isDeepStrictEqual } from 'node:util';
import { hashSnapshot } from '../../../scripts/lib/simScenarioDriver.mjs';

const root = process.cwd();
const helperRoot = '.devshots/lantern-ward/merged-baseline-diagnosis';
const evidenceRoot = 'docs/validation/lantern-ward/evidence';
const jsonPath = `${evidenceRoot}/merged-baseline-diagnosis.json`;
const logPath = `${evidenceRoot}/merged-baseline-diagnosis.log`;
const refreshOwned = process.argv.includes('--refresh-owned-evidence');
assert.ok(refreshOwned || (!existsSync(jsonPath) && !existsSync(logPath)), 'do not overwrite released evidence');
const candidate = '8cf0034e814ef18af14dcc52f26485e637820e57';
const controller = 'f71edbfcbccb33c2fbc424116c6684b4ed7596ad';
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex');
const valueSha = (value) => sha(JSON.stringify(value));
const load = (path) => JSON.parse(readFileSync(path, 'utf8'));
const capture = (label) => load(`${helperRoot}/${label}.json`);
const normalizeEol = (text) => text.replace(/\r\n?/g, '\n');

function diff(before, after, path = '$', output = []) {
  if (isDeepStrictEqual(before, after)) return output;
  if (before == null || after == null || typeof before !== 'object' || typeof after !== 'object'
      || Array.isArray(before) !== Array.isArray(after)) {
    output.push({ path, before, after }); return output;
  }
  for (const key of [...new Set([...Object.keys(before), ...Object.keys(after)])].sort()) {
    const child = Array.isArray(before) ? `${path}[${key}]` : `${path}.${key}`;
    if (!Object.hasOwn(before, key)) output.push({ path: child, added: after[key] });
    else if (!Object.hasOwn(after, key)) output.push({ path: child, removed: before[key] });
    else diff(before[key], after[key], child, output);
  }
  return output;
}

const indexes = ['paired-runs', 'controls-runs', 'v3-reload600-runs'].map((name) => load(`${helperRoot}/${name}.json`));
const runs = indexes.flatMap((index) => index.runs);
for (const run of runs) {
  assert.equal(run.exitCode, 0);
  assert.equal(sha(readFileSync(run.stdoutPath)), run.stdoutSha256);
  assert.equal(sha(readFileSync(run.stderrPath)), run.stderrSha256);
  assert.equal(run.stderrBytes, 0);
}
const expectedPaths = {
  v3: 'test/47a.telemetry.v3.native-contact.expected.json',
  legacy: 'test/47a.telemetry.expected.json',
};
const comparisons = [];
for (const [label, flight, reloadAt] of [['v3', 'v3', 60], ['legacy', 'legacy', 600], ['v3-reload600', 'v3', 600]]) {
  const before = capture(`controller-${label}`), after = capture(`current-${label}`);
  const envelope = load(expectedPaths[flight]);
  const expected = envelope.acceptanceCriteria.authoritativeHashByReloadAt?.[String(reloadAt)]
    || envelope.acceptanceCriteria.authoritativeHash;
  assert.equal(before.sha256, expected, 'the controller must reproduce the recorded golden');
  assert.equal(hashSnapshot(before.snapshot), before.sha256);
  assert.equal(hashSnapshot(after.snapshot), after.sha256);
  const snapshotDiffs = diff(before.snapshot, after.snapshot);
  assert.deepEqual(snapshotDiffs, [{ path: '$.meta.version', before: 22, after: 23 }]);
  const normalized = structuredClone(after.snapshot);
  normalized.meta.version = before.snapshot.meta.version;
  const normalizedHash = hashSnapshot(normalized);
  assert.equal(normalizedHash, expected);
  assert.deepEqual(normalized, before.snapshot);
  assert.equal(after.diagnosticMotionFrames.length, 720);
  assert.ok(after.diagnosticMotionFrames.every((frame, index) => frame[0] === index + 1));
  const compared = {};
  for (const field of ['metrics', 'traceSummary', 'trace', 'combatTrace', 'diagnosticMotionFrames']) {
    const differences = diff(before[field], after[field]);
    assert.deepEqual(differences, [], `${label} ${field} must be identical`);
    compared[field] = { differences, beforeSha256: valueSha(before[field]), afterSha256: valueSha(after[field]) };
  }
  assert.deepEqual(before.snapshot.physics, after.snapshot.physics);
  comparisons.push({
    label, flight, reloadAt, seed: 47, ticks: 720, runtimeProfile: 'legacy47a',
    expectedPath: expectedPaths[flight], expectedHash: expected,
    controllerHash: before.sha256, candidateHash: after.sha256,
    completeCanonicalSnapshotDiffs: snapshotDiffs,
    candidateWithOnlyMetaVersion22Hash: normalizedHash,
    candidateWithOnlyMetaVersion22EqualsControllerSnapshot: true,
    compared, metrics: after.metrics, traceSummary: after.traceSummary,
    traceRecordCount: after.trace.records.length,
    motionFrames: after.diagnosticMotionFrames.length,
    observedEntityRows: after.diagnosticMotionFrames.reduce((sum, frame) => sum + frame[1].length, 0),
    motionColumns: after.diagnosticSources.motionColumns,
    motionObservation: after.diagnosticSources.observer,
    finalEntities: after.snapshot.entities.map(({ id, type, pos, vel, rot, hull, shield, cap }) => ({ id, type, pos, vel, rot, hull, shield, cap })),
    nativeBodies: after.snapshot.physics,
    commonMotionWitnessAtTick54: after.diagnosticMotionFrames[53],
    controllerSourceOverrides: before.diagnosticSources.overrides,
    sourceObservation: { controller: before.diagnosticSources, candidate: after.diagnosticSources },
  });
}

const controls = [];
for (const flight of ['v3', 'legacy']) {
  const controlled = capture(`version-only-${flight}`), before = capture(`controller-${flight}`), after = capture(`current-${flight}`);
  assert.equal(controlled.diagnosticSources.overrides.length, 1);
  assert.equal(controlled.diagnosticSources.overrides[0].path, 'src/data/saveVersion.js');
  assert.equal(controlled.sha256, before.sha256);
  const differences = {};
  for (const field of ['snapshot', 'metrics', 'traceSummary', 'trace', 'combatTrace', 'diagnosticMotionFrames']) {
    differences[field] = diff(before[field], controlled[field]);
    assert.deepEqual(differences[field], []);
  }
  assert.deepEqual(controlled.diagnosticMotionFrames, after.diagnosticMotionFrames);
  controls.push({
    flight, reloadAt: controlled.reloadAt, sourceGraph: candidate,
    singleOverride: controlled.diagnosticSources.overrides[0],
    controlledHash: controlled.sha256, controllerHash: before.sha256,
    candidateUnmodifiedHash: after.sha256, completeControllerComparisonDiffs: differences,
    motionFrames: controlled.diagnosticMotionFrames.length,
    traceRecords: controlled.trace.records.length,
    matchesControllerSnapshotAndAllObservedTelemetry: true,
  });
}

const priorContract = normalizeEol(execFileSync('git', ['show', `${candidate}:SAVE_SCHEMA.md`], { encoding: 'utf8' }));
const controllerSchema = normalizeEol(readFileSync(`${helperRoot}/schema-controller.md`, 'utf8'));
const currentSchema = normalizeEol(readFileSync(`${helperRoot}/schema-current.md`, 'utf8'));
assert.equal(priorContract, controllerSchema);
const table = (markdown) => Object.fromEntries([...markdown.matchAll(/^\| `([^`]+)` \| ([^|]+) \| (.*) \|$/gm)]
  .map((match) => [match[1], { type: match[2], sample: match[3] }]));
const beforeTable = table(controllerSchema), afterTable = table(currentSchema);
assert.equal(Object.keys(beforeTable).length, 465);
assert.deepEqual(Object.keys(beforeTable), Object.keys(afterTable));
const schemaTableDiffs = diff(beforeTable, afterTable);
assert.deepEqual(schemaTableDiffs, [{ path: '$.$.meta.version.sample', before: '22', after: '23' }]);
const section = (markdown, name) => markdown.split(`## ${name}\n\n`)[1].split('\n## ')[0].trim();
assert.equal(section(controllerSchema, 'Data Key Order'), section(currentSchema, 'Data Key Order'));
let schemaUnifiedDiff = '';
try {
  execFileSync('diff', ['-u', '--label', 'controller/SAVE_SCHEMA.md', '--label', 'generated-v23/SAVE_SCHEMA.md',
    `${helperRoot}/schema-controller.md`, `${helperRoot}/schema-current.md`], { encoding: 'utf8' });
} catch (error) {
  assert.equal(error.status, 1);
  schemaUnifiedDiff = error.stdout;
}
const schemaDiagnosis = {
  priorPinnedContractMatchesControllerGenerator: true,
  controllerVersion: 22, candidateVersion: 23,
  totalSerializedPathsBefore: 465, totalSerializedPathsAfter: 465,
  descendantPathsBefore: 464, descendantPathsAfter: 464,
  pathAdditions: [], pathRemovals: [], dataKeyOrderChanged: false,
  serializedSampleDiffs: [{ path: '$.meta.version', before: 22, after: 23 }],
  migrationStepAdded: { from: 22, to: 23 },
  migrationCoverage: 'Existing v1 through v21 fixtures now reach v23; v22 fixture coverage is added.',
  controllerGeneratedSha256: sha(controllerSchema), candidateGeneratedSha256: sha(currentSchema),
  currentWorkingContractMatchesGenerator: normalizeEol(readFileSync('SAVE_SCHEMA.md', 'utf8')) === currentSchema,
  proposedAction: 'Integration owner regenerates SAVE_SCHEMA.md with the existing generator. No generator, schema writer, or runtime change is needed.',
  unifiedDiff: schemaUnifiedDiff,
};

const proposedMetadataChanges = [];
for (const flight of ['v3', 'legacy']) {
  const comparison = comparisons.find((row) => row.label === flight);
  const operations = [{ op: 'replace', path: '/acceptanceCriteria/authoritativeHash', before: comparison.expectedHash, value: comparison.candidateHash }];
  if (flight === 'v3') {
    for (const reloadAt of ['60', '600']) operations.push({ op: 'replace', path: `/acceptanceCriteria/authoritativeHashByReloadAt/${reloadAt}`,
      before: comparison.expectedHash, value: comparison.candidateHash });
  }
  operations.push({ op: 'add', path: '/notes/-', value:
    `2026-11-05 Lantern Ward save-version migration: controller f71edbfcbccb33c2fbc424116c6684b4ed7596ad and integrated 8cf0034e814ef18af14dcc52f26485e637820e57, seed 47/tick 720/${flight === 'v3' ? 'reload at 60 and 600' : 'reload at 600'}, differ only at $.meta.version (22->23). Every other canonical snapshot field, metric, full existing event/combat trace, and all 720 per-step entity motion/vitals samples match. No additive field accounts for this hash change.` });
  operations.push({ op: 'add', path: '/notes/-', value:
    `A single-module negative control loading only f71 src/data/saveVersion.js into the current runtime reproduces prior hash ${comparison.expectedHash}. The version 23 hash is ${comparison.candidateHash}. Source/capture hashes and complete semantic-diff evidence are in docs/validation/lantern-ward/evidence/merged-baseline-diagnosis.json. The input tape, scenario, physics owner, event counts/families, acceptance bounds, and five-run requirement remain unchanged.` });
  proposedMetadataChanges.push({ path: expectedPaths[flight], status: 'PROPOSED ONLY; independent review and integration-owner authorization required before any fixture edit', operations });
}

const sourceFiles = ['src/data/saveVersion.js', 'src/save/migrations.js', 'src/core/simSnapshot.js', 'scripts/lib/simScenarioDriver.mjs',
  'scripts/sf-sim-cli.mjs', 'test/47a.inputs.json', 'src/data/scenarios/47a.scenario.json', ...Object.values(expectedPaths)];
for (const path of Object.values(expectedPaths)) assert.equal(sha(readFileSync(path)), sha(execFileSync('git', ['show', `${candidate}:${path}`])));
const record = {
  schema: 'spaceface.lanternWardBaselineDiagnosis.v1',
  producedUtc: new Date().toISOString(),
  verdict: 'VERSION_ONLY',
  conclusion: 'Both observed 47-A authoritative-hash failures are fully accounted for by $.meta.version changing 22 to 23. No other canonical state leaf, observed motion/vitals sample, existing event/combat trace, metric, or final native-body field changed in the paired routes. The stale generated schema has version/migration/coverage-only drift.',
  candidate, candidateTree: git('rev-parse', `${candidate}^{tree}`), controller, controllerTree: git('rev-parse', `${controller}^{tree}`),
  headAtFinish: git('rev-parse', 'HEAD'), trackedProductionDiffAtFinish: git('diff', '--name-status', 'HEAD', '--', 'src', 'scripts'),
  method: {
    repositoryCopies: 0, baselineReruns: 0, productionEdits: 0, expectedFixtureEdits: 0, schemaWritesByThisAgent: 0,
    runs: 'Eight serial 720-tick diagnostic inspect captures and two read-only schema stdout generations. No run/expect/repeat gate was rerun.',
    controllerOverlay: 'For modules changed between f71 and the candidate, Node synchronous module load hooks supply git-show f71 bytes in memory. New-only controller imports fail closed. Unchanged modules use the same clean working source. Each actually substituted module is recorded with its SHA-256.',
    observation: 'An identical read-only CLI instrumentation retains the existing deterministic event/combat trace and records primitive entity motion/vitals after each normal sim.step. It neither changes input nor writes state. Final hashes from the unchanged canonical snapshot/hash functions match both the original failure and reference expectations.',
    scope: 'The curated legacy47a runtime profile, seed 47, existing input tape, 720 ticks: V3 reload at 60 and 600, legacy reload at 600. These diagnostics are not a new public gameplay, GPU, performance, whole-Adventure, or repeat-count qualification.',
    protected: 'No expected hash, bound, repeat requirement, input tape, scenario contract, simulation clock, physics writer, runtime profile, or baseline command was changed.',
    analysisHelperSetupCorrection: 'The first aggregate-analysis invocation used one excess parent directory in its hashSnapshot import and exited before reading captures or writing evidence. The helper import was corrected; no simulation capture was rerun.',
  },
  originalBaseline: {
    logPath: `${evidenceRoot}/merged-relevant-baseline.log`, logSha256: sha(readFileSync(`${evidenceRoot}/merged-relevant-baseline.log`)),
    receiptPath: `${evidenceRoot}/merged-relevant-baseline.json`, receipt: load(`${evidenceRoot}/merged-relevant-baseline.json`),
  },
  sourceFileSha256: Object.fromEntries(sourceFiles.map((path) => [path, sha(readFileSync(path))])),
  diagnosticHelpers: Object.fromEntries(['loader.mjs', 'capture.py', 'analyze.mjs'].map((name) => {
    const path = `${helperRoot}/${name}`, raw = readFileSync(path);
    return [name, { path, sha256: sha(raw), source: raw.toString('utf8') }];
  })),
  runs, comparisons, singleModuleNegativeControls: controls, schemaDiagnosis, proposedMetadataChanges,
};
assert.equal(record.headAtFinish, candidate);
assert.equal(record.trackedProductionDiffAtFinish, '');
const log = [
  'Lantern Ward merged baseline diagnosis',
  `Produced: ${record.producedUtc}`,
  `Candidate: ${candidate} tree ${record.candidateTree}`,
  `Controller: ${controller} tree ${record.controllerTree}`,
  '',
  'VERDICT: VERSION_ONLY',
  record.conclusion,
  '',
  'Complete canonical snapshot delta for every paired route: $.meta.version 22 -> 23.',
  'No added or removed canonical snapshot paths. All 720 observed motion/vitals frames match per route.',
  'Full existing event traces, combat traces, metrics and final native bodies match. Frame values are recorded without numeric rounding.',
  '',
  ...comparisons.flatMap((row) => [
    `${row.flight} reload${row.reloadAt}:`,
    `  controller/recorded: ${row.controllerHash}`,
    `  candidate:           ${row.candidateHash}`,
    `  only-version-reversed capture: ${row.candidateWithOnlyMetaVersion22Hash}`,
    `  ${row.motionFrames} motion frames, ${row.observedEntityRows} entity rows, ${row.traceRecordCount} trace records; all paired telemetry identical.`,
    `  raw motion SHA256: ${row.compared.diagnosticMotionFrames.afterSha256}`,
  ]),
  '',
  'Actual runtime negative controls (current graph, only saveVersion.js supplied from f71):',
  ...controls.map((row) => `  ${row.flight} reload${row.reloadAt}: ${row.controlledHash}; all captured state and telemetry equal controller.`),
  '',
  'Save schema: 465 total paths in both versions, including root $; 464 descendants. No data-key/path addition or removal.',
  'Only version 22 -> 23, migration 22 -> 23, migration coverage to 23 and $.meta.version sample change.',
  'Schema diff (blank context lines displayed without trailing whitespace; exact raw diff retained in JSON):',
  schemaUnifiedDiff.split('\n').map((line) => line.trimEnd()).join('\n'),
  '',
  'Captured command receipts (all serial, exit 0, stderr empty):',
  ...runs.map((run) => `  ${run.label}: ${run.elapsedWallMs.toFixed(6)}ms; SPACEFACE_BASELINE_DIAG_MODE=${run.mode} ${run.argv.join(' ')}\n    stdout ${run.stdoutPath} (${run.stdoutBytes} bytes, SHA256 ${run.stdoutSha256})`),
  '',
  'Proposed metadata updates only; no fixtures changed by this diagnosis:',
  ...proposedMetadataChanges.flatMap((change) => [change.path, JSON.stringify(change.operations, null, 2)]),
  '',
  record.method.scope,
  'Original failing baseline evidence is preserved. No baseline rerun, second checkout, reset, stash, source edit, expected-file edit or schema write by this agent.',
  '',
].join('\n');
record.logSha256 = sha(log);
writeFileSync(logPath, log, { flag: refreshOwned ? 'w' : 'wx' });
writeFileSync(jsonPath, JSON.stringify(record, null, 2) + '\n', { flag: refreshOwned ? 'w' : 'wx' });
console.log(JSON.stringify({ verdict: record.verdict, comparisons: comparisons.map(({ label, controllerHash, candidateHash, completeCanonicalSnapshotDiffs, motionFrames, traceRecordCount }) => ({ label, controllerHash, candidateHash, completeCanonicalSnapshotDiffs, motionFrames, traceRecordCount })),
  controls: controls.map(({ flight, controlledHash }) => ({ flight, controlledHash })),
  schemaTotalPaths: 465, jsonPath, logPath, jsonSha256: sha(readFileSync(jsonPath)), logSha256: record.logSha256 }, null, 2));
